glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1);
  gl_Position = pos;
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 meltColor;
  vec4 restColor;
  float time;
  float useRestColor;
};

void main () {
  vec4 texColor = texture(texture, v_uv0) * v_color;
  float height = texColor.b;
  if (height < time) {
    if (useRestColor == 1.0) {
      texColor = vec4(restColor.xyz, texColor.a);
    } else {
      discard;
    }
  } else if (height < time + 0.04) {
    texColor = vec4(meltColor.xyz, texColor.a);
  }
  vec4 o = texColor;
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

